import{demoRoutes,demoFeed}from './demo.mjs';
import{MotionTrack,makePath,pointAt,clamp}from './motion.mjs';
const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let routes=demoRoutes,visible=new Set(routes.map(r=>r.id)),mode='demo',config=null,tracks=new Map(),markers=new Map(),selected=null,paused=false,stopsShown=true,motionOn=!matchMedia('(prefers-reduced-motion: reduce)').matches,simMs=0,lastDemo=-10000,lastReceived=null,lastUi=0,liveTimer=null,modeGeneration=0;
let map,routeLayers,stopLayers;
let catalog=null,catalogPromise=null,catalogDraft=new Set(),activeRouteIds=[],maxActiveRoutes=3,catalogBusy=false,livePollMs=null;
if(window.L){map=L.map('map',{zoomControl:false,minZoom:10,maxZoom:18}).setView([37.389,127.119],14);L.control.zoom({position:'topright'}).addTo(map);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',keepBuffer:1});let errors=0;tiles.on('tileerror',()=>{if(++errors>3)showError('배경지도 연결이 원활하지 않습니다. 경로·시연 차량은 계속 표시됩니다.');});tiles.addTo(map);routeLayers=L.layerGroup().addTo(map);stopLayers=L.layerGroup().addTo(map);}else{$('map-fallback').hidden=false;showError('지도 구성 요소를 불러오지 못했습니다. 페이지를 새로고침해 주세요.');}
function showError(message){$('error-banner').textContent=message;$('error-banner').hidden=!message;}
function routeFor(id){return routes.find(r=>r.id===id);}
function fitMap(){if(!map)return;const shown=routes.filter(r=>visible.has(r.id)),bundang=mode==='live'?shown.flatMap(r=>r.stops.filter(s=>s.inBundang).map(s=>[s.coordinates[1],s.coordinates[0]])):[];const points=bundang.length?bundang:shown.flatMap(r=>r.points.map(p=>[p[1],p[0]]));if(points.length)map.fitBounds(points,{paddingTopLeft:[45,120],paddingBottomRight:[45,280],maxZoom:14});}
function renderRoutes(){
 $('route-count').textContent=routes.length+'개';$('route-list').innerHTML=routes.map(r=>`<label class="route-row" style="--route-color:${r.color}"><span class="route-badge">${esc(r.name)}</span><span><strong>${esc(r.label)}</strong><small>${r.source==='simulation'?'시연 경로 · '+r.stops.length+'개 지점':'공식 형상 · 정류소 기준'}</small></span><input type="checkbox" data-route="${esc(r.id)}" aria-label="${esc(r.label)} 표시" ${visible.has(r.id)?'checked':''}></label>`).join('');
 $('route-list').querySelectorAll('input').forEach(input=>input.onchange=()=>{input.checked?visible.add(input.dataset.route):visible.delete(input.dataset.route);renderMapRoutes();renderBuses();if(!tracks.get(selected)||!visible.has(tracks.get(selected).sample.routeId))selectFirst();});renderMapRoutes();
}
function renderMapRoutes(){if(!map)return;routeLayers.clearLayers();stopLayers.clearLayers();for(const r of routes){if(!visible.has(r.id))continue;L.polyline(r.points.map(p=>[p[1],p[0]]),{color:'white',weight:9,opacity:.95}).addTo(routeLayers);L.polyline(r.points.map(p=>[p[1],p[0]]),{color:r.color,weight:5,opacity:.8,dashArray:r.source==='simulation'?'2 1':null}).addTo(routeLayers);if(stopsShown)for(const s of r.stops){L.circleMarker([s.coordinates[1],s.coordinates[0]],{radius:5,color:r.color,weight:2,fillColor:'white',fillOpacity:1}).bindTooltip(esc(s.name),{permanent:false,direction:'top',className:'stop-label'}).addTo(stopLayers);}}}
function icon(sample){const r=routeFor(sample.routeId);return L.divIcon({className:'bus-marker',html:`<div class="vehicle-pin ${sample.id===selected?'selected':''}" style="--route-color:${r.color}">${esc(r.name.length>4?'B':r.name)}</div>`,iconSize:[39,39],iconAnchor:[19,44]});}
function renderBuses(){const values=[...tracks.values()].filter(t=>visible.has(t.sample.routeId));$('bus-count').textContent=values.length+'대';$('bus-list').innerHTML=values.length?values.map(t=>{const r=routeFor(t.sample.routeId);return `<button class="bus-row ${t.sample.id===selected?'selected':''}" data-bus="${esc(t.sample.id)}" style="--route-color:${r.color}"><span class="mini">${esc(r.name.length>3?'B':r.name)}</span><strong>${esc(t.sample.label)}</strong><span>${mode==='demo'?'시연':'정류소 기준'} ›</span></button>`;}).join(''):'<p class="empty">표시할 차량이 없습니다.<br>선택한 구간이나 운행정보를 확인하세요.</p>';$('bus-list').querySelectorAll('button').forEach(b=>b.onclick=()=>selectBus(b.dataset.bus,true));
 if(!map)return;for(const [id,m]of markers){if(!tracks.has(id)||!visible.has(tracks.get(id).sample.routeId)){map.removeLayer(m);markers.delete(id);}}
 for(const t of values){const p=pointAt(routeFor(t.sample.routeId).path,t.motion.at(clock()));if(!markers.has(t.sample.id)){const marker=L.marker([p[1],p[0]],{icon:icon(t.sample),keyboard:true,title:t.sample.label}).addTo(map).on('click',()=>selectBus(t.sample.id,false));markers.set(t.sample.id,marker);}else markers.get(t.sample.id).setIcon(icon(t.sample));}
}
function selectFirst(){selected=[...tracks.values()].find(t=>visible.has(t.sample.routeId))?.sample.id??null;renderBuses();updateDetails();}
function selectBus(id,pan){selected=id;renderBuses();updateDetails();if(pan&&map&&markers.has(id))map.panTo(markers.get(id).getLatLng());}
function clock(){return mode==='demo'?simMs:Date.now();}
function ingest(samples){const present=new Set();for(const sample of samples){if(!Number.isFinite(sample.meters))continue;present.add(sample.id);const old=tracks.get(sample.id);if(old&&!old.invalidated){old.motion.ingest(sample);old.sample=sample;}else tracks.set(sample.id,{sample,motion:new MotionTrack(sample)});}for(const id of tracks.keys())if(!present.has(id))tracks.delete(id);lastReceived=clock();if(!tracks.has(selected))selected=samples.find(s=>tracks.has(s.id))?.id??null;renderBuses();}
function updateDetails(){const t=tracks.get(selected);if(!t||!visible.has(t.sample.routeId)){$('selected-title').textContent='선택된 버스 없음';$('selected-subtitle').textContent='구간을 선택해 차량을 확인하세요.';$('selected-route').textContent='—';$('speed').innerHTML='— <small>km/h</small>';$('next-stop').textContent='—';$('data-state').textContent='표시할 정보 없음';$('route-progress').style.width='0';return;}
 const r=routeFor(t.sample.routeId),now=clock(),meters=motionOn?t.motion.at(now):t.motion.to,stale=mode==='live'&&now-t.sample.time>Math.max(90000,(livePollMs||config?.pollMs||60000)*1.5),next=r.stops.find(s=>s.meters>meters+5)||r.stops.at(-1);
 $('selected-route').textContent=r.name;$('selected-route').style.setProperty('--route-color',r.color);$('selected-title').textContent=t.sample.label;$('selected-subtitle').textContent=r.label;$('speed').innerHTML=(stale||t.motion.speed==null?'—':Math.round(t.motion.speed))+' <small>km/h</small>';$('next-stop').textContent=next?.name||'확인 불가';$('next-label').textContent=mode==='demo'?'다음 시연 지점':'다음 정류소 (추정)';$('data-state').textContent=paused?'시연 일시정지':stale?'수신 지연':t.motion.reason;$('route-progress').style.width=clamp(meters/r.path.total*100,0,100)+'%';$('route-progress').style.background=r.color;
 $('selection-note').textContent=mode==='demo'?'시연 데이터를 보간한 움직임입니다. 실제 운행정보가 아닙니다.':'정류소 기준 위치를 연결한 추정입니다. 실제 차량 좌표·순간 속도가 아닙니다.';
}
function reset(){clearTimeout(liveTimer);tracks.clear();for(const m of markers.values())map?.removeLayer(m);markers.clear();selected=null;lastReceived=null;showError('');}
function selectionChanged(){return catalogDraft.size!==activeRouteIds.length||activeRouteIds.some(id=>!catalogDraft.has(id));}
function renderCatalog(){
 const entries=catalog?.routes||[],query=$('catalog-search').value.trim().toLocaleLowerCase(),matches=entries.filter(r=>[r.name,r.label,r.startStationName,r.endStationName].some(value=>String(value||'').toLocaleLowerCase().includes(query)));
 $('catalog-count').textContent=catalog?entries.length+'개':'';
 $('catalog-coverage').textContent=catalog?.coverage?.gbisCreatedDate?`GBIS ${catalog.coverage.gbisCreatedDate} · 정류장 자료 ${catalog.coverage.cityStopDataDate} 기준. 신설·미수록 노선은 누락될 수 있습니다.`:'';
 $('catalog-selected').innerHTML=entries.filter(r=>catalogDraft.has(r.id)).map(r=>`<button type="button" class="catalog-chip" data-remove-route="${esc(r.id)}" aria-label="${esc(r.name)} 선택 해제" ${catalogBusy?'disabled':''}>${esc(r.name)} <span aria-hidden="true">×</span></button>`).join('');
 $('catalog-selected').querySelectorAll('button').forEach(button=>button.onclick=()=>{catalogDraft.delete(button.dataset.removeRoute);renderCatalog();$('catalog-search').focus();});
 $('catalog-message').textContent=catalogBusy?'노선을 불러오는 중입니다.':!catalog?'노선 목록을 불러오지 못했습니다.':!entries.length?'확인된 분당 경유 노선이 없습니다.':`${catalogDraft.size}/${maxActiveRoutes}개 선택 · ${matches.length}개 검색 결과${catalogDraft.size>=maxActiveRoutes?' · 다른 노선을 고르려면 선택을 해제하세요.':!catalogDraft.size?' · 1개 이상 골라주세요.':selectionChanged()?' · 적용 버튼으로 변경하세요.':''}`;
 $('catalog-list').innerHTML=matches.length?matches.map(r=>`<label class="catalog-row"><input type="checkbox" data-catalog-route="${esc(r.id)}" ${catalogDraft.has(r.id)?'checked':''} ${catalogBusy||(!catalogDraft.has(r.id)&&catalogDraft.size>=maxActiveRoutes)?'disabled':''}><span><strong>${esc(r.name)} <small>${esc(r.routeTypeName||'')}</small></strong><span>${esc(r.startStationName||'기점 확인 중')} → ${esc(r.endStationName||'종점 확인 중')}</span><small>분당 경유${Number.isFinite(r.bundangStopCount)?' '+r.bundangStopCount+'개 정류소':''}</small></span></label>`).join(''):catalog&&!catalogBusy?'<p class="empty">검색 결과가 없습니다.</p>':'';
 $('catalog-list').querySelectorAll('input').forEach(input=>input.onchange=()=>{const id=input.dataset.catalogRoute;if(input.checked&&catalogDraft.size<maxActiveRoutes)catalogDraft.add(id);else catalogDraft.delete(id);renderCatalog();[...$('catalog-list').querySelectorAll('input')].find(next=>next.dataset.catalogRoute===id)?.focus();});
 $('apply-routes').disabled=catalogBusy||!catalog||catalogDraft.size<1||catalogDraft.size>maxActiveRoutes||!selectionChanged();
 $('apply-routes').textContent=catalogBusy?'노선 불러오는 중…':!selectionChanged()&&activeRouteIds.length?'선택한 노선 표시 중':'선택 노선 적용';
 $('catalog-poll-note').textContent=activeRouteIds.length&&livePollMs?`표시 중 ${activeRouteIds.length}개 · 약 ${Math.ceil(livePollMs/1000)}초마다 갱신`:`최대 ${maxActiveRoutes}개 노선을 골라 적용하세요.`;
}
async function loadCatalog(){
 if(catalog)return catalog;if(catalogPromise)return catalogPromise;
 catalogPromise=(async()=>{const response=await fetch('/api/catalog');if(!response.ok)throw new Error((await response.json()).error||'노선 목록 조회 실패');const result=await response.json();if(!Array.isArray(result.routes))throw new Error('노선 목록을 확인할 수 없습니다.');catalog={...result,routes:result.routes.map(r=>({...r,id:String(r.id)}))};maxActiveRoutes=Math.max(1,Math.min(3,Number(result.maxActiveRoutes)||Number(config?.maxActiveRoutes)||3));const allowed=new Set(catalog.routes.map(r=>r.id));catalogDraft=new Set((config?.routeIds||[]).map(String).filter(id=>allowed.has(id)).slice(0,maxActiveRoutes));return catalog;})();
 try{return await catalogPromise;}finally{catalogPromise=null;}
}
async function switchLive(){
 if(!config?.ready){$('data-dialog').showModal();return;}if(mode==='live'&&catalog){$('catalog-search').focus();return;}
 modeGeneration++;const generation=modeGeneration;reset();mode='live';paused=false;routes=[];visible=new Set();activeRouteIds=[];livePollMs=null;catalogBusy=true;renderRoutes();updateDetails();setModeLabels();renderCatalog();$('map-label').textContent='노선 목록 조회 중';
 try{await loadCatalog();if(generation!==modeGeneration)return;catalogBusy=false;renderCatalog();if(catalogDraft.size)await applySelectedRoutes();else $('map-label').textContent='노선을 선택해 주세요';}catch(e){if(generation!==modeGeneration)return;catalogBusy=false;renderCatalog();$('map-label').textContent='노선 목록 조회 실패';showError(e.message);}
}
async function applySelectedRoutes(){
 if(mode!=='live'||catalogBusy||catalogDraft.size<1||catalogDraft.size>maxActiveRoutes)return;modeGeneration++;const generation=modeGeneration;reset();activeRouteIds=[...catalogDraft];livePollMs=null;routes=[];visible=new Set();catalogBusy=true;renderRoutes();updateDetails();setModeLabels();renderCatalog();$('map-label').textContent='노선 조회 중';
 try{const response=await fetch('/api/routes?ids='+encodeURIComponent(activeRouteIds.join(',')));if(!response.ok)throw new Error((await response.json()).error||'노선 조회 실패');const data=await response.json();if(generation!==modeGeneration)return;routes=data.map(r=>({...r,path:makePath(r.points)}));visible=new Set(routes.map(r=>r.id));setModeLabels();renderRoutes();fitMap();await fetchLive(generation);}catch(e){if(generation!==modeGeneration)return;activeRouteIds=[];$('map-label').textContent='노선 조회 실패';showError(e.message);updateDetails();}finally{if(generation===modeGeneration){catalogBusy=false;renderCatalog();}}
}
async function fetchLive(generation){try{const response=await fetch('/api/live?ids='+encodeURIComponent(activeRouteIds.join(',')));if(!response.ok)throw new Error((await response.json()).error||'위치 조회 실패');const result=await response.json();if(generation!==modeGeneration)return;livePollMs=Math.max(15000,Number(result.pollMs)||Number(config.pollMs)||60000);renderCatalog();const samples=result.values.flatMap(v=>v.rows.flatMap(row=>{const r=routeFor(row.routeId),s=r?.stops.find(s=>s.seq===row.stationSeq&&s.id===row.stationId);return s&&s.matchError<=200?[{...row,meters:s.meters,time:v.observedAt}]:[];}));ingest(samples);showError('');}catch(e){if(generation!==modeGeneration)return;showError(e.message+' · 수신 전 위치를 유지합니다.');for(const t of tracks.values()){t.motion.from=t.motion.at(clock());t.motion.to=t.motion.from;t.motion.duration=0;t.motion.speed=null;t.motion.reason='수신 지연';t.invalidated=true;}}finally{if(generation===modeGeneration&&mode==='live')liveTimer=setTimeout(()=>fetchLive(generation),Math.max(15000,livePollMs||Number(config.pollMs)||60000));}}
function switchDemo(){modeGeneration++;reset();mode='demo';routes=demoRoutes;visible=new Set(routes.map(r=>r.id));simMs=0;lastDemo=-10000;paused=false;setModeLabels();renderRoutes();ingest(demoFeed(0,0));fitMap();}
function setModeLabels(){$('demo-mode').classList.toggle('active',mode==='demo');$('live-mode').classList.toggle('active',mode==='live');$('demo-mode').setAttribute('aria-pressed',mode==='demo');$('live-mode').setAttribute('aria-pressed',mode==='live');$('route-catalog').hidden=mode!=='live';$('route-section-title').textContent=mode==='demo'?'표시 구간':'지도에 표시할 노선';$('mode-note').innerHTML=mode==='demo'?'시연 차량과 예시 경로입니다.<br>실제 운행·정류장 위치가 아닙니다.':'GBIS 정류소 상태를 바탕으로 위치를 추정합니다.<br>차량 GPS 좌표는 제공되지 않습니다.';$('map-label').textContent=mode==='demo'?'시연 중':'GBIS 관측';$('caption-source').textContent=mode==='demo'?'지리적 예시 경로 / 시뮬레이션':'GBIS 공식 노선 형상 / 정류소 기준 추정';$('tracking-badge').textContent=mode==='demo'?'시연 위치':'정류소 기준';$('pause').hidden=mode!=='demo';$('pause').textContent='일시정지';$('pause').setAttribute('aria-pressed','false');$('data-mode').textContent=mode==='demo'?'시뮬레이션':'GBIS 상태 관측';}
$('catalog-search').oninput=renderCatalog;$('apply-routes').onclick=applySelectedRoutes;
$('demo-mode').onclick=switchDemo;$('live-mode').onclick=switchLive;$('fit-map').onclick=fitMap;$('open-data').onclick=()=>$('data-dialog').showModal();$('close-data').onclick=()=>$('data-dialog').close();$('data-dialog').addEventListener('click',e=>{if(e.target===$('data-dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close();}});
$('toggle-stops').onclick=()=>{stopsShown=!stopsShown;$('toggle-stops').setAttribute('aria-pressed',stopsShown);renderMapRoutes();};
function motionLabel(){$('toggle-motion').textContent=motionOn?'보간 켜짐':'보간 꺼짐';$('toggle-motion').setAttribute('aria-pressed',motionOn);}motionLabel();$('toggle-motion').onclick=()=>{motionOn=!motionOn;motionLabel();};
$('pause').onclick=()=>{paused=!paused;$('pause').textContent=paused?'시연 재생':'일시정지';$('pause').setAttribute('aria-pressed',paused);$('map-label').textContent=paused?'시연 정지':'시연 중';};
renderRoutes();ingest(demoFeed(0,0));fitMap();fetch('/api/status').then(r=>r.ok?r.json():null).then(data=>config=data).catch(()=>{});
let previous=performance.now();function frame(now){const delta=now-previous;previous=now;if(mode==='demo'&&!paused&&!document.hidden){simMs+=Math.min(delta,1000);if(simMs-lastDemo>=10000){ingest(demoFeed(simMs/1000,simMs));lastDemo=simMs;}}
 if(!paused){for(const [id,m]of markers){const t=tracks.get(id);if(!t)continue;const r=routeFor(t.sample.routeId),p=pointAt(r.path,motionOn?t.motion.at(clock()):t.motion.to);m.setLatLng([p[1],p[0]]);}}
 if(now-lastUi>500){updateDetails();$('update-age').textContent=lastReceived===null?'수신 대기':Math.max(0,Math.floor((clock()-lastReceived)/1000))+'초 전 수신';lastUi=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
